import sys
from datetime import datetime, timedelta


def parse_time(time_str):
    return datetime.strptime(time_str, "%H:%M")


def overlaps(s1, e1, s2, e2):
    return not (e1 <= s2 or e2 <= s1)


def total_time(bookings):
    total = timedelta()
    for _, _, _, s, e in bookings:
        total += (parse_time(e) - parse_time(s))
    hours, remainder = divmod(total.seconds // 3600, 60)
    minutes = remainder
    return f"{hours}:{minutes:02}"


def main():
    bookings = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "book":
            if len(parts) != 6:
                continue
            bid, room, day, start_str, end_str = parts[1], parts[2], parts[3], parts[4], parts[5]
            try:
                start = parse_time(start_str)
                end = parse_time(end_str)
            except ValueError:
                print(f"INVALID {bid}")
                continue
            if end <= start:
                print(f"INVALID {bid}")
            else:
                conflict = None
                for other_bid, other_room, other_day, other_start, other_end in bookings:
                    if other_room == room and other_day == day and overlaps(
                        start, end, other_start, other_end
                    ):
                        conflict = other_bid
                        break
                if conflict:
                    print(f"REJECT {bid} {conflict}")
                else:
                    bookings.append((bid, room, day, start_str, end_str))
                    print(f"ACCEPT {bid}")
        elif parts[0] == "cancel":
            if len(parts) != 2:
                continue
            bid = parts[1]
            bookings = [
                b for b in bookings if b[0] != bid
            ]  # Cancel by id
            if bid not in [b[0] for b in bookings]:
                print(f"UNKNOWN {bid}")
            else:
                print(f"CANCELLED {bid}")
        else:
            continue

    rooms = {}
    for bid, room, day, _, _ in bookings:
        rooms[room] = rooms.get(room, 0) + 1

    for room in sorted(rooms):
        print(f"{room} {rooms[room]} {total_time([b for b in bookings if b[1] == room])}")


if __name__ == "__main__":
    main()
